import{_ as s,o as e,c as a,ag as l}from"./chunks/framework.CAXxHpAX.js";const r=JSON.parse('{"title":"官网与文档站维护","description":"","frontmatter":{},"headers":[],"relativePath":"guide/site-maintenance.md","filePath":"guide/site-maintenance.md","lastUpdated":null}'),t={name:"guide/site-maintenance.md"};function d(o,i,c,n,p,h){return e(),a("div",null,[...i[0]||(i[0]=[l(`<h1 id="官网与文档站维护" tabindex="-1">官网与文档站维护 <a class="header-anchor" href="#官网与文档站维护" aria-label="Permalink to &quot;官网与文档站维护&quot;">​</a></h1><p>本文档说明 Deepsight 官网与文档站的目录结构、更新方式和部署流程。站点基于 <code>VitePress</code>，源码放在仓库内的 <code>site/</code> 目录，文档真源仍然保持在根目录 <code>docs/</code>。</p><h2 id="_1-目录分工" tabindex="-1">1. 目录分工 <a class="header-anchor" href="#_1-目录分工" aria-label="Permalink to &quot;1. 目录分工&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Deepsight/</span></span>
<span class="line"><span>├── docs/                      # 文档真源</span></span>
<span class="line"><span>├── site/                      # VitePress 站点</span></span>
<span class="line"><span>│   ├── index.md               # 官网首页</span></span>
<span class="line"><span>│   ├── guide/                 # 构建前生成的站内文档副本（不追踪）</span></span>
<span class="line"><span>│   ├── public/assets/         # 从 docs/assets 同步的文档资源（不追踪）</span></span>
<span class="line"><span>│   ├── public/brand/          # 站点品牌资源（追踪）</span></span>
<span class="line"><span>│   ├── scripts/sync-docs.mjs  # 文档同步脚本</span></span>
<span class="line"><span>│   └── .vitepress/            # 站点配置与主题</span></span>
<span class="line"><span>└── .gitlab-ci.yml             # 主发布流程：GitLab CI 构建站点并推送到 GitHub Pages 仓库</span></span></code></pre></div><ul><li><code>docs/</code>：作为文档的单一事实来源，日常只需要维护这里。</li><li><code>site/index.md</code>：官网首页，单独维护，不从 <code>docs/</code> 自动生成。</li><li><code>site/guide/</code>：由脚本自动生成，不要手动编辑。</li><li><code>site/public/assets/</code>：由脚本从 <code>docs/assets/</code> 同步生成。</li><li><code>site/public/brand/</code>：站点 Logo、favicon 等品牌资源，需要纳入版本控制。</li></ul><h2 id="_2-本地更新流程" tabindex="-1">2. 本地更新流程 <a class="header-anchor" href="#_2-本地更新流程" aria-label="Permalink to &quot;2. 本地更新流程&quot;">​</a></h2><p>首次使用前，请先安装 Node.js 20 或更高版本，然后执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>日常维护站点时，按下面流程进行：</p><ol><li>修改根目录 <code>docs/</code> 下的设计文档、开发文档或安装文档</li><li>如需调整官网文案，再修改 <code>site/index.md</code></li><li>在 <code>site/</code> 目录运行本地预览</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>这个命令会先执行 <code>scripts/sync-docs.mjs</code>，把 <code>docs/</code> 中的内容同步到站点目录，然后启动本地开发服务器。</p><h2 id="_3-构建命令" tabindex="-1">3. 构建命令 <a class="header-anchor" href="#_3-构建命令" aria-label="Permalink to &quot;3. 构建命令&quot;">​</a></h2><p>仅同步文档：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:sync</span></span></code></pre></div><p>构建静态站点：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>构建结果位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>site/.vitepress/dist/</span></span></code></pre></div><p>以下目录不应纳入 Git 追踪：</p><ul><li><code>site/guide/</code></li><li><code>site/public/assets/</code></li><li><code>site/.vitepress/dist/</code></li><li><code>site/node_modules/</code></li></ul><h2 id="_4-自动同步范围" tabindex="-1">4. 自动同步范围 <a class="header-anchor" href="#_4-自动同步范围" aria-label="Permalink to &quot;4. 自动同步范围&quot;">​</a></h2><p>同步脚本当前会处理以下内容：</p><ul><li><code>docs/*.md</code></li><li><code>docs/dev/*.md</code></li><li><code>docs/use/*.md</code></li><li><code>docs/assets/*</code></li></ul><p>并自动完成以下转换：</p><ul><li>文档复制到 <code>site/guide/</code></li><li>图片路径从相对路径改写为 <code>/assets/...</code></li><li>按 <code>docs/</code> 目录结构自动映射到站内路径</li><li>对少数首页级文档应用稳定 slug 别名，例如 <code>01_deepsight.md -&gt; overview.md</code></li></ul><p>后续新增普通文档时，不需要修改同步脚本，脚本会自动发现并映射。只有在你希望某个文档使用特定 slug 时，才需要调整：</p><ul><li><code>site/scripts/sync-docs.mjs</code> 中的 <code>slugOverrides</code></li><li><code>site/.vitepress/config.ts</code> 中的 <code>sidebar</code></li></ul><h2 id="_5-主发布流程-gitlab-ci-github-pages-仓库" tabindex="-1">5. 主发布流程：GitLab CI -&gt; GitHub Pages 仓库 <a class="header-anchor" href="#_5-主发布流程-gitlab-ci-github-pages-仓库" aria-label="Permalink to &quot;5. 主发布流程：GitLab CI -&gt; GitHub Pages 仓库&quot;">​</a></h2><p>推荐方案是：</p><ol><li>主代码仓库继续托管在学校 GitLab</li><li>单独创建一个 GitHub 仓库，仅用于托管静态站点</li><li>GitLab CI 在主仓库里构建 <code>site/.vitepress/dist</code></li><li>GitLab CI 将构建产物推送到 GitHub Pages 仓库</li></ol><p>这样做的结果是：</p><ul><li>GitHub 不需要托管你的完整源码</li><li>GitHub 仓库里只保留网站静态文件</li><li>GitHub Pages 只承担站点发布职责</li></ul><h3 id="_5-1-准备一个-github-pages-仓库" tabindex="-1">5.1 准备一个 GitHub Pages 仓库 <a class="header-anchor" href="#_5-1-准备一个-github-pages-仓库" aria-label="Permalink to &quot;5.1 准备一个 GitHub Pages 仓库&quot;">​</a></h3><p>创建一个公开 GitHub 仓库，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-github-user/deepsight-site</span></span></code></pre></div><p>这个仓库只用于承载静态站点内容，不需要同步 Go 源码。</p><h3 id="_5-2-配置-github-pages-仓库" tabindex="-1">5.2 配置 GitHub Pages 仓库 <a class="header-anchor" href="#_5-2-配置-github-pages-仓库" aria-label="Permalink to &quot;5.2 配置 GitHub Pages 仓库&quot;">​</a></h3><p>在该 GitHub 仓库中：</p><ol><li>进入 <code>Settings -&gt; Pages</code></li><li>选择从分支部署</li><li>选择 <code>main</code> 分支和 <code>/ (root)</code> 目录</li></ol><p>如果后续绑定了自定义域名，GitHub Pages 会直接从这个仓库对外提供站点。</p><h3 id="_5-3-在-gitlab-中配置-ci-变量" tabindex="-1">5.3 在 GitLab 中配置 CI 变量 <a class="header-anchor" href="#_5-3-在-gitlab-中配置-ci-变量" aria-label="Permalink to &quot;5.3 在 GitLab 中配置 CI 变量&quot;">​</a></h3><p>在 GitLab 项目的 <code>Settings -&gt; CI/CD -&gt; Variables</code> 中添加：</p><ul><li><code>GITHUB_PAGES_REPO</code><ul><li>值示例：<code>your-github-user/deepsight-site</code></li></ul></li><li><code>GITHUB_PAGES_BRANCH</code><ul><li>值示例：<code>main</code></li></ul></li><li><code>GITHUB_PAGES_TOKEN</code><ul><li>GitHub Personal Access Token，至少需要目标仓库的写权限</li></ul></li></ul><p>建议将 <code>GITHUB_PAGES_TOKEN</code> 标记为 masked 和 protected。</p><p>如果你使用的是 GitHub Fine-grained PAT，至少授予目标仓库：</p><ul><li><code>Contents: Read and write</code></li><li><code>Metadata: Read</code></li></ul><p>如果你使用的是 Classic PAT，常见做法是授予：</p><ul><li><code>repo</code></li></ul><h3 id="_5-4-发布触发条件" tabindex="-1">5.4 发布触发条件 <a class="header-anchor" href="#_5-4-发布触发条件" aria-label="Permalink to &quot;5.4 发布触发条件&quot;">​</a></h3><p>仓库中的 <code>.gitlab-ci.yml</code> 会在 <code>main</code> 分支发生以下变更时触发发布：</p><ul><li><code>docs/**</code></li><li><code>site/**</code></li><li><code>README.md</code></li><li><code>.gitlab-ci.yml</code></li><li><code>scripts/ci/deploy_site_to_github_pages.sh</code></li></ul><p>CI 任务会执行：</p><ol><li>安装站点依赖</li><li>执行 <code>npm run docs:build</code></li><li>将 <code>site/.vitepress/dist</code> 推送到 GitHub Pages 仓库</li></ol><h2 id="_5-5-首次部署检查清单" tabindex="-1">5.5 首次部署检查清单 <a class="header-anchor" href="#_5-5-首次部署检查清单" aria-label="Permalink to &quot;5.5 首次部署检查清单&quot;">​</a></h2><p>首次接通这条链路时，建议按以下顺序检查：</p><ol><li>在本地确认 <code>cd site &amp;&amp; npm run docs:build</code> 可以成功</li><li>确认 GitHub Pages 目标仓库已经创建</li><li>确认目标仓库默认分支与 <code>GITHUB_PAGES_BRANCH</code> 一致</li><li>确认目标仓库已开启 Pages，并指向该分支根目录</li><li>确认 GitLab CI 变量已经配置完毕</li><li>向 GitLab 主仓库的 <code>main</code> 分支推送一次与站点相关的提交</li><li>在 GitLab CI 查看 <code>deploy_site_to_github_pages</code> 任务日志</li><li>到 GitHub Pages 目标仓库确认静态文件是否已经更新</li></ol><h2 id="_6-自定义域名" tabindex="-1">6. 自定义域名 <a class="header-anchor" href="#_6-自定义域名" aria-label="Permalink to &quot;6. 自定义域名&quot;">​</a></h2><p>如果使用自己的域名，建议直接将 GitHub Pages 绑定到自定义域名，例如：</p><ul><li><code>docs.example.com</code></li><li><code>deepsight.example.com</code></li></ul><p>此时在 <code>site/.vitepress/config.ts</code> 中使用：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">base</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/&quot;</span></span></code></pre></div><p>然后在 GitHub Pages 仓库的 Pages 设置中填写自定义域名，并在你的 DNS 提供商处配置对应记录。</p><p>如果你希望在每次 GitLab CI 发布时保留 GitHub 仓库中的 <code>CNAME</code> 文件，当前发布脚本已经默认不会删除它。</p><h2 id="_7-维护纪律" tabindex="-1">7. 维护纪律 <a class="header-anchor" href="#_7-维护纪律" aria-label="Permalink to &quot;7. 维护纪律&quot;">​</a></h2><ul><li>技术文档只维护一份，优先修改根目录 <code>docs/</code></li><li>不要手动编辑 <code>site/guide/</code> 下的生成文件</li><li>官网首页是对外叙事层，不要把所有技术细节都堆进去</li><li>图片与架构图统一放在 <code>docs/assets/</code></li><li>站点改动合并前，至少本地运行一次 <code>npm run docs:build</code></li><li>正式发布链路以 GitLab CI 为准，GitHub 仓库只作为静态站点发布目标</li></ul>`,66)])])}const g=s(t,[["render",d]]);export{r as __pageData,g as default};
